import{z as n,x as i,o as e,c as C,q as r,j as o,D as A,d as s,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CSMA 与交换","description":"","frontmatter":{"title":"CSMA 与交换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csma-switch.md","filePath":"cs/csma-switch.md","lastUpdated":1791063341000}'),p={name:"cs/csma-switch.md"};function d(D,a,c,m,M,F){const t=i("Mermaid");return e(),C("div",null,[a[2]||(a[2]=r('<h1 id="csma-与交换" tabindex="-1">CSMA 与交换 <a class="header-anchor" href="#csma-与交换" aria-label="Permalink to &quot;CSMA 与交换&quot;">​</a></h1><div class="epigraph"><p>载波监听多路访问在发送前听介质；交换式以太网把冲突域缩小到链路，用转发表按 MAC 转发。</p><footer>—— 据 Metcalfe and Boggs, 1976；Kurose and Ross 对 CSMA/CD 与交换的整理</footer></div><p><a href="/cs/frame-crc">上一课</a>给出帧与 MAC。共享同轴或集线器上，两台同时发会破坏信号。缺口是介质访问：<strong>CSMA/CD</strong>；以及当代默认：<strong>交换机</strong>学习 MAC、转发帧，冲突域不再是整个局域网。本课不把生成树环路写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 ALOHA 冲突浪费大。CSMA：发前听；CD：边发边听，冲突则发拥塞信号并二进制退避。交换：每端口独立缓冲，根据目的 MAC 只从对应端口送出；未知则泛洪。缺口不是新的帧格式，而是从「大家抢一根线」到「按地址点到点转发」。</p><p><span class="marginnote">二进制退避给个数字实例：第一次冲突后从 0、1 里随机挑一个时隙等待；再撞就从 0–3 挑；再撞 0–7……每次翻倍。撞过越多次，彼此挑中不同数的概率越大，网络自动&quot;降温&quot;，这是 CD 能收敛的关键。</span></p><p>全双工交换链路上不再用 CD，CSMA 作为共享介质与半双工的历史机制保留在对照里。</p><p><span class="marginnote">冲突域：一处冲突大家都能检测到的范围。广播域：广播帧能到达的范围。交换机分割冲突域，默认不分割广播域。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集线器：电气中继，一个冲突域。交换机：收完整帧（或直通），查 MAC 表，命中则单端口发送，表项由源 MAC 学习、老化删除。未知目的、广播、组播：向除入端口外泛洪。本课假定无环拓扑；有环则泛洪放大，下一课生成树。</p>',10)),(e(),o(l,null,{default:A(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HUB%5B%22%E9%9B%86%E7%BA%BF%E5%99%A8%3A%20%E4%B8%80%E4%B8%AA%E5%86%B2%E7%AA%81%E5%9F%9F%22%5D%20--%3E%20CSMA%5B%22CSMA%2FCD%20%E9%80%80%E9%81%BF%22%5D%0A%20%20SW%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%3A%20%E5%AD%A6%E6%BA%90%20MAC%22%5D%20--%3E%20FWD%5B%22%E6%8C%89%E7%9B%AE%E7%9A%84%E7%AB%AF%E5%8F%A3%E8%BD%AC%E5%8F%91%22%5D%0A%20%20FWD%20--%3E%20FLOOD%5B%22%E6%9C%AA%E7%9F%A5%E5%88%99%E6%B3%9B%E6%B4%AA%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"交换把链路层做成小规模的「路由」，但键是 MAC 不是前缀。DMA 进来的帧在交换机里可能再 DMA 出去，主机 OS 看不见。端到端仍不在这一层完成：交换机可以丢帧，FCS 只到下一跳。与 IP 的分工：同一广播域内靠 MAC 到主机，跨网要后课 IP。",-1)),a[5]||(a[5]=E("p",null,"学习表会错（主机挪端口）靠老化；恶意灌表留给安全课。",-1)),(e(),o(l,null,{default:A(()=>[B(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%B8%A7%E5%88%B0%E8%BE%BE%E7%AB%AF%E5%8F%A3%20P1%22%5D%20--%3E%20L%5B%22%E5%AD%A6%E4%B9%A0%EF%BC%9A%E6%8A%8A%E6%BA%90%20MAC%20%E8%AE%B0%E5%88%B0%20P1%22%5D%0A%20%20L%20--%3E%20LOOK%7B%22%E8%A1%A8%E9%87%8C%E6%9C%89%E7%9B%AE%E7%9A%84%20MAC%EF%BC%9F%22%7D%0A%20%20LOOK%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20F%5B%22%E5%8F%AA%E4%BB%8E%E5%AF%B9%E5%BA%94%E7%AB%AF%E5%8F%A3%E5%8F%91%E5%87%BA%22%5D%0A%20%20LOOK%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%7C%20FL%5B%22%E9%99%A4%E5%85%A5%E7%AB%AF%E5%8F%A3%E5%A4%96%E6%B3%9B%E6%B4%AA%22%5D%0A%20%20FL%20--%3E%20R%5B%22%E7%9B%AE%E7%9A%84%E6%9C%BA%E5%9B%9E%E5%B8%A7%EF%BC%8C%E5%8F%8D%E6%96%B9%E5%90%91%E8%A2%AB%E5%AD%A6%E5%88%B0%22%5D%0A%20%20R%20--%3E%20T%5B%22%E8%A1%A8%E9%A1%B9%E9%9D%A0%E8%80%81%E5%8C%96%E8%B6%85%E6%97%B6%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">泛洪可以想成&quot;不知道收件人住哪，就整栋楼喊一嗓子&quot;：目的主机回话时，交换机从回帧的来向学到它挂在哪个端口，下次就只敲那一家的门，不用再喊。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入数据中心的 TRILL/SPB 作为主干，不把流量控制 PAUSE 帧写完。也不把无线 CSMA/CA 的全部 NAV 机制展开，只承认无线不能「边发边听」故用 CA。环路与广播风暴，下一课。</p><p>直通交换降低延迟，但可能转发 FCS 错误的帧；存储转发等整帧校验完再送。教学默认存储转发。</p><p><span class="marginnote">初学者容易以为交换机转发前一定检查整帧对不对。直通模式像传话不留底：刚读到目的 MAC 就开转，省时间但会把坏帧也传出去；存储转发像先收好整封信、验完封口再递，慢一点但不传播坏帧。</span></p><p>交换机缓冲占满时仍会丢帧，CSMA 的退避救不了全双工口上的拥塞。</p><p>后课默认：交换按 MAC 转发，未知泛洪。有冗余链路时必须先成树，下一课生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSMA/CD 解决共享介质冲突；交换缩小冲突域。</li><li>交换机学源、转目的、未知泛洪。</li><li>环路需要生成树。</li><li>出处：Metcalfe and Boggs；Kurose and Ross；IEEE 802.3。</li></ul>',9))])}const S=n(p,[["render",d]]);export{u as __pageData,S as default};
